5|using Markdig.Helpers;
6|using Markdig.Syntax;
7|
8|namespace Markdig.Parsers;
9|
10|/// <summary>
11|/// A block parser for a <see cref="QuoteBlock"/>.
12|/// </summary>
13|/// <seealso cref="BlockParser" />
14|public class QuoteBlockParser : BlockParser
15|{
16|    /// <summary>
17|    /// Initializes a new instance of the <see cref="QuoteBlockParser"/> class.
18|    /// </summary>
19|    public QuoteBlockParser()
20|    {
21|        OpeningCharacters = ['>'];
22|    }
23|
24|    /// <summary>
25|    /// Attempts to open a block at the current parser position.
26|    /// </summary>
27|    public override BlockState TryOpen(BlockProcessor processor)
28|    {
29|        if (processor.IsCodeIndent)
30|        {
31|            return BlockState.None;
32|        }
33|
34|        var sourcePosition = processor.Start;
35|
36|        // 5.1 Block quotes 
37|        // A block quote marker consists of 0-3 spaces of initial indent, plus (a) the character > together with a following space, or (b) a single character > not followed by a space.
38|        var quoteChar = processor.CurrentChar;
39|        var column = processor.Column;
40|        var c = processor.NextChar();
41|
42|        var quoteBlock = new QuoteBlock(this)
43|        {
44|            QuoteChar = quoteChar,
45|            Column = column,
46|            Span = new SourceSpan(sourcePosition, processor.Line.End),
47|        };
48|
49|        if (processor.TrackTrivia)
50|        {
51|            quoteBlock.LinesBefore = processor.TakeLinesBefore();
52|        }
53|
54|        bool hasSpaceAfterQuoteChar = false;
55|        if (c == ' ')
56|        {
57|            processor.NextColumn();
58|            hasSpaceAfterQuoteChar = true;
59|            processor.SkipFirstUnwindSpace = true;
60|        }
61|        else if (c == '\t')
62|        {
63|            processor.NextColumn();
64|        }
65|
66|        if (processor.TrackTrivia)
67|        {
68|            var triviaBefore = processor.UseTrivia(sourcePosition - 1);
69|            StringSlice triviaAfter = StringSlice.Empty;
70|            bool wasEmptyLine = false;
71|            if (processor.Line.IsEmptyOrWhitespace())
72|            {
73|                processor.TriviaStart = processor.Start;
74|                triviaAfter = processor.UseTrivia(processor.Line.End);
75|                wasEmptyLine = true;
76|            }
77|
78|            if (!wasEmptyLine)
79|            {
80|                processor.TriviaStart = processor.Start;
81|            }
82|
83|            quoteBlock.QuoteLines.Add(new QuoteBlockLine
84|            {
85|                TriviaBefore = triviaBefore,
86|                TriviaAfter = triviaAfter,
87|                QuoteChar = true,
88|                HasSpaceAfterQuoteChar = hasSpaceAfterQuoteChar,
89|                NewLine = processor.Line.NewLine,
90|            });
91|        }
92|
93|        processor.NewBlocks.Push(quoteBlock);
94|        return BlockState.Continue;
95|    }
96|
97|    /// <summary>
98|    /// Attempts to continue parsing the specified block.
99|    /// </summary>
100|    public override BlockState TryContinue(BlockProcessor processor, Block block)
101|    {
102|        if (processor.IsCodeIndent)
103|        {
104|            return BlockState.None;
105|        }
106|
107|        var quote = (QuoteBlock) block;
108|        var sourcePosition = processor.Start;
109|
110|        // 5.1 Block quotes 
111|        // A block quote marker consists of 0-3 spaces of initial indent, plus (a) the character > together with a following space, or (b) a single character > not followed by a space.
112|        var c = processor.CurrentChar;
113|        if (c != quote.QuoteChar)
114|        {
115|            if (processor.IsBlankLine)
116|            {
117|                return BlockState.BreakDiscard;
118|            }
119|            else
120|            {
121|                if (processor.TrackTrivia)
122|                {
123|                    quote.QuoteLines.Add(new QuoteBlockLine
124|                    {
125|                        QuoteChar = false,
126|                        NewLine = processor.Line.NewLine,
127|                    });
128|                }
129|                return BlockState.None;
130|            }
131|        }
132|
133|        bool hasSpaceAfterQuoteChar = false;
134|        c = processor.NextChar(); // Skip quote marker char
135|        if (c == ' ')
136|        {
137|            processor.NextColumn();
138|            hasSpaceAfterQuoteChar = true;
139|            processor.SkipFirstUnwindSpace = true;
140|        }
141|        else if (c == '\t')
142|        {
143|            processor.NextColumn();
144|        }
145|
146|        if (processor.TrackTrivia)
147|        {
148|            var triviaSpaceBefore = processor.UseTrivia(sourcePosition - 1);
149|            StringSlice triviaAfter = StringSlice.Empty;
150|            bool wasEmptyLine = false;
151|            if (processor.Line.IsEmptyOrWhitespace())
152|            {
153|                processor.TriviaStart = processor.Start;
154|                triviaAfter = processor.UseTrivia(processor.Line.End);
155|                wasEmptyLine = true;
156|            }
157|            quote.QuoteLines.Add(new QuoteBlockLine
158|            {
159|                QuoteChar = true,
160|                HasSpaceAfterQuoteChar = hasSpaceAfterQuoteChar,
161|                TriviaBefore = triviaSpaceBefore,
162|                TriviaAfter = triviaAfter,
163|                NewLine = processor.Line.NewLine,
164|            });
165|
166|            if (!wasEmptyLine)
167|            {
168|                processor.TriviaStart = processor.Start;
169|            }
170|        }
171|
172|        block.UpdateSpanEnd(processor.Line.End);
173|        return BlockState.Continue;
174|    }
