94|        return BlockState.Continue;
95|    }
96|
97|    /// <summary>
98|    /// Attempts to continue parsing the specified block.
99|    /// </summary>
100|    public override BlockState TryContinue(BlockProcessor processor, Block block)
101|    {
102|        if (processor.IsCodeIndent)
103|        {
104|            return BlockState.None;
105|        }
106|
107|        var quote = (QuoteBlock) block;
108|        var sourcePosition = processor.Start;
109|
110|        // 5.1 Block quotes 
111|        // A block quote marker consists of 0-3 spaces of initial indent, plus (a) the character > together with a following space, or (b) a single character > not followed by a space.
112|        var c = processor.CurrentChar;
113|        if (c != quote.QuoteChar)
114|        {
115|            if (processor.IsBlankLine)
116|            {
117|                return BlockState.BreakDiscard;
118|            }
119|            else
120|            {
121|                if (processor.TrackTrivia)
122|                {
123|                    quote.QuoteLines.Add(new QuoteBlockLine
124|                    {
125|                        QuoteChar = false,
126|                        NewLine = processor.Line.NewLine,
127|                    });
128|                }
129|                return BlockState.None;
130|            }
131|        }
132|
133|        bool hasSpaceAfterQuoteChar = false;
134|        c = processor.NextChar(); // Skip quote marker char
135|        if (c == ' ')
136|        {
137|            processor.NextColumn();
138|            hasSpaceAfterQuoteChar = true;
139|            processor.SkipFirstUnwindSpace = true;
140|        }
141|        else if (c == '\t')
142|        {
143|            processor.NextColumn();
144|        }
145|
146|        if (processor.TrackTrivia)
147|        {
148|            var triviaSpaceBefore = processor.UseTrivia(sourcePosition - 1);
149|            StringSlice triviaAfter = StringSlice.Empty;
150|            bool wasEmptyLine = false;
151|            if (processor.Line.IsEmptyOrWhitespace())
152|            {
153|                processor.TriviaStart = processor.Start;
154|                triviaAfter = processor.UseTrivia(processor.Line.End);
155|                wasEmptyLine = true;
156|            }
157|            quote.QuoteLines.Add(new QuoteBlockLine
158|            {
159|                QuoteChar = true,
160|                HasSpaceAfterQuoteChar = hasSpaceAfterQuoteChar,
161|                TriviaBefore = triviaSpaceBefore,
162|                TriviaAfter = triviaAfter,
163|                NewLine = processor.Line.NewLine,
164|            });
165|
166|            if (!wasEmptyLine)
167|            {
168|                processor.TriviaStart = processor.Start;
169|            }
170|        }
171|
172|        block.UpdateSpanEnd(processor.Line.End);
173|        return BlockState.Continue;
174|    }
