7|/// <summary>
8|/// Base class for an ordered list item parser.
9|/// </summary>
10|/// <seealso cref="ListItemParser" />
11|public abstract class OrderedListItemParser : ListItemParser
12|{
13|    /// <summary>
14|    /// Initializes a new instance of the <see cref="OrderedListItemParser"/> class.
15|    /// </summary>
16|    protected OrderedListItemParser()
17|    {
18|        OrderedDelimiters = ['.', ')'];
19|    }
20|
21|    /// <summary>
22|    /// Gets or sets the ordered delimiters used after a digit/number (by default `.` and `)`)
23|    /// </summary>
24|    public char[] OrderedDelimiters { get; set; }
25|
26|    /// <summary>
27|    /// Utility method that tries to parse the delimiter coming after an ordered list start (e.g: the `)` after `1)`).
28|    /// </summary>
29|    /// <param name="state">The state.</param>
30|    /// <param name="orderedDelimiter">The ordered delimiter found if this method is successful.</param>
31|    /// <returns><c>true</c> if parsing was successful; <c>false</c> otherwise.</returns>
32|    protected bool TryParseDelimiter(BlockProcessor state, out char orderedDelimiter)
33|    {
34|        // Check if we have an ordered delimiter
35|        orderedDelimiter = state.CurrentChar;
36|        foreach (char delimiter in OrderedDelimiters)
37|        {
38|            if (delimiter == orderedDelimiter)
39|            {
40|                state.NextChar();
41|                return true;
42|            }
43|        }
44|        return false;
45|    }
