5|using Markdig.Helpers;
6|using Markdig.Syntax;
7|
8|namespace Markdig.Parsers;
9|
10|/// <summary>
11|/// A parser for a list block and list item block.
12|/// </summary>
13|/// <seealso cref="BlockParser" />
14|public class ListBlockParser : BlockParser
15|{
16|    private CharacterMap<ListItemParser>? mapItemParsers;
17|
18|    /// <summary>
19|    /// Initializes a new instance of the <see cref="ListBlockParser"/> class.
20|    /// </summary>
21|    public ListBlockParser()
22|    {
23|        ItemParsers = new OrderedList<ListItemParser>()
24|        {
25|            new UnorderedListItemParser(),
26|            new NumberedListItemParser()
27|        };
28|    }
29|
30|    /// <summary>
31|    /// Gets the parsers for items.
32|    /// </summary>
33|    public OrderedList<ListItemParser> ItemParsers { get; }
34|
35|    /// <summary>
36|    /// Performs the initialize operation.
37|    /// </summary>
38|    public override void Initialize()
39|    {
40|        var tempMap = new Dictionary<char, ListItemParser>();
41|
42|        foreach (var itemParser in ItemParsers)
43|        {
44|            if (itemParser.OpeningCharacters is null)
45|            {
46|                ThrowHelper.InvalidOperationException($"The list item parser of type [{itemParser.GetType()}] cannot have OpeningCharacters to null. It must define a list of valid opening characters");
47|            }
48|
49|            foreach (var openingCharacter in itemParser.OpeningCharacters)
50|            {
51|                if (tempMap.ContainsKey(openingCharacter))
52|                {
53|                    ThrowHelper.InvalidOperationException(
54|                        $"A list item parser with the same opening character `{openingCharacter}` is already registered");
55|                }
56|                tempMap.Add(openingCharacter, itemParser);
57|            }
58|        }
59|        mapItemParsers = new CharacterMap<ListItemParser>(tempMap);
60|    }
61|
62|    /// <summary>
63|    /// Attempts to open a block at the current parser position.
64|    /// </summary>
65|    public override BlockState TryOpen(BlockProcessor processor)
66|    {
67|        // When both a thematic break and a list item are possible
68|        // interpretations of a line, the thematic break takes precedence
69|        var thematicParser = ThematicBreakParser.Default;
70|        if (thematicParser.HasOpeningCharacter(processor.CurrentChar))
71|        {
72|            var result = thematicParser.TryOpen(processor);
73|            if (result.IsBreak())
74|            {
75|                return result;
76|            }
77|        }
78|
79|        return TryParseListItem(processor, null);
80|    }
81|
82|    /// <summary>
83|    /// Attempts to continue parsing the specified block.
84|    /// </summary>
85|    public override BlockState TryContinue(BlockProcessor processor, Block block)
86|    {
87|        if (block is ListBlock && processor.NextContinue is ListItemBlock)
88|        {
89|            // We try to match only on item block if the ListBlock
90|            return BlockState.Skip;
91|        }
92|
93|        // When both a thematic break and a list item are possible
94|        // interpretations of a line, the thematic break takes precedence
95|        BlockState result;
96|        var thematicParser = ThematicBreakParser.Default;
97|        if (processor.LastBlock is not FencedCodeBlock && thematicParser.HasOpeningCharacter(processor.CurrentChar))
98|        {
99|            result = thematicParser.TryOpen(processor);
100|            if (result.IsBreak())
101|            {
102|                // TODO: We remove the thematic break, as it will be created later, but this is inefficient, try to find another way
103|                var thematicBreak = processor.NewBlocks.Pop();
104|
105|                if (processor.TrackTrivia)
106|                {
107|                    processor.LinesBefore = thematicBreak.LinesBefore;
108|                }
109|
110|                return BlockState.None;
111|            }
112|        }
113|
114|        // 5.2 List items
115|        // TODO: Check with specs, it is not clear that list marker or bullet marker must be followed by at least 1 space
116|
117|        // If we have already a ListItemBlock, we are going to try to append to it
118|        result = BlockState.None;
119|        if (block is ListItemBlock listItem)
120|        {
121|            result = TryContinueListItem(processor, listItem);
122|        }
123|
124|        if (result == BlockState.None)
125|        {
126|            result = TryParseListItem(processor, block);
127|        }
128|
129|        return result;
130|    }
131|
132|    private BlockState TryContinueListItem(BlockProcessor state, ListItemBlock listItem)
133|    {
134|        var list = (ListBlock)listItem.Parent!;
135|
136|        // Allow all blanks lines if the last block is a fenced code block
137|        // Allow 1 blank line inside a list
138|        // If > 1 blank line, terminate this list
139|        if (state.IsBlankLine)
140|        {
141|            if (state.CurrentBlock != null && state.CurrentBlock.IsBreakable)
142|            {
143|                if (!(state.NextContinue is ListBlock))
144|                {
145|                    list.CountAllBlankLines++;
146|                    if (!state.TrackTrivia)
147|                    {
148|                        listItem.Add(new BlankLineBlock());
149|                    }
150|                }
151|                list.CountBlankLinesReset++;
152|            }
153|
154|            if (list.CountBlankLinesReset == 1 && listItem.ColumnWidth < 0)
155|            {
156|                state.Close(listItem);
157|                list.CountBlankLinesReset = 0;
158|
159|                // Leave the list open
160|                list.IsOpen = true;
161|                return BlockState.Continue;
162|            }
163|
164|            // Update list-item source end position
165|            listItem.UpdateSpanEnd(state.Line.End);
166|
167|            return BlockState.Continue;
168|        }
169|
170|        list.CountBlankLinesReset = 0;
171|
172|        int columnWidth = listItem.ColumnWidth;
173|        if (columnWidth < 0)
174|        {
175|            columnWidth = -columnWidth;
176|        }
177|
178|        if (state.Indent >= columnWidth)
179|        {
180|            if (state.Indent > columnWidth && state.IsCodeIndent)
181|            {
182|                state.GoToColumn(state.ColumnBeforeIndent + columnWidth);
183|            }
184|
185|            // Update list-item source end position
186|            listItem.UpdateSpanEnd(state.Line.End);
187|            listItem.NewLine = state.Line.NewLine;
188|
189|            return BlockState.Continue;
190|        }
191|
192|        return BlockState.None;
193|    }
194|
195|    private BlockState TryParseListItem(BlockProcessor state, Block? block)
196|    {
197|        var currentListItem = block as ListItemBlock;
198|        var currentParent = block as ListBlock ?? (ListBlock)currentListItem?.Parent!;
199|
200|        // We can early exit if we have a code indent and we are either (1) not in a ListItem, (2) preceded by a blank line, (3) in an unordered list
201|        if (state.IsCodeIndent && (currentListItem is null || currentListItem.LastChild is BlankLineBlock || !currentParent.IsOrdered))
202|        {
203|            return BlockState.None;
204|        }
205|
206|        var initColumnBeforeIndent = state.ColumnBeforeIndent;
207|        var initColumn = state.Column;
208|        var sourcePosition = state.Start;
209|        var sourceEndPosition = state.Line.End;
210|
211|        var c = state.CurrentChar;
212|        var itemParser = mapItemParsers![c];
213|        if (itemParser is null)
214|        {
215|            return BlockState.None;
216|        }
217|
218|        // Try to parse the list item
219|        if (!itemParser.TryParse(state, currentParent?.BulletType ?? '\0', out ListInfo listInfo))
220|        {
221|            // Reset to an a start position
222|            state.GoToColumn(initColumn);
223|            return BlockState.None;
224|        }
225|        var savedTriviaStart = state.TriviaStart;
226|        var triviaBefore = state.UseTrivia(sourcePosition - 1);
227|
228|        // set trivia to the mandatory whitespace after the bullet
229|        state.TriviaStart = state.Start;
230|
231|        bool isOrdered = itemParser is OrderedListItemParser;
232|
233|        // Gets the current character after a successful parsing of the list information
234|        c = state.CurrentChar;
235|
236|        // Item starting with a blank line
237|        int columnWidth;
238|
239|        // Do we have a blank line right after the bullet?
240|        if (c == '\0')
241|        {
242|            // Use a negative number to store the number of expected chars
243|            columnWidth = -(state.Column - initColumnBeforeIndent + 1);
244|        }
245|        else
246|        {
247|            if (!c.IsSpaceOrTab())
248|            {
249|                state.GoToColumn(initColumn);
250|                state.TriviaStart = savedTriviaStart; // restore changed TriviaStart state
251|                return BlockState.None;
252|            }
253|
254|            // Parse the following indent
255|            state.RestartIndent();
256|            var columnBeforeIndent = state.Column;
257|            state.ParseIndent();
258|
259|            // We expect at most 4 columns after
260|            // If we have more, we reset the position
261|            if (state.Indent > 4)
262|            {
263|                state.GoToColumn(columnBeforeIndent + 1);
264|            }
265|
266|            // Number of spaces required for the following content to be part of this list item
267|            // If the list item starts with a blank line, the number of spaces
268|            // following the list marker doesn't change the required indentation
269|            columnWidth = (state.IsBlankLine ? columnBeforeIndent : state.Column) - initColumnBeforeIndent;
270|        }
271|
272|        // Starts/continue the list unless:
273|        // - an empty list item follows a paragraph
274|        // - an ordered list is not starting by '1'
275|        block ??= state.LastBlock;
276|        if (block is not null && block.IsParagraphBlock)
277|        {
278|            if (state.IsBlankLine ||
279|                state.IsOpen(block) && listInfo.BulletType == '1' && listInfo.OrderedStart is not "1")
280|            {
281|                state.GoToColumn(initColumn);
282|                state.TriviaStart = savedTriviaStart; // restore changed TriviaStart state
283|                return BlockState.None;
284|            }
285|        }
286|
287|        int.TryParse(listInfo.OrderedStart, out int order);
288|        var newListItem = new ListItemBlock(this)
289|        {
290|            Column = initColumn,
291|            ColumnWidth = columnWidth,
292|            Order = order,
293|            Span = new SourceSpan(sourcePosition, sourceEndPosition),
294|        };
295|
296|        if (state.TrackTrivia)
297|        {
298|            newListItem.TriviaBefore = triviaBefore;
299|            newListItem.LinesBefore = state.TakeLinesBefore();
300|            newListItem.NewLine = state.Line.NewLine;
301|            newListItem.SourceBullet = listInfo.SourceBullet;
302|        }
303|
304|        state.NewBlocks.Push(newListItem);
305|
306|        if (currentParent != null)
307|        {
308|            // If we have a new list item, close the previous one
309|            if (currentListItem != null)
310|            {
311|                state.Close(currentListItem);
312|            }
313|
314|            // Reset the list if it is a new list or a new type of bullet
315|            if (currentParent.IsOrdered != isOrdered ||
316|                currentParent.OrderedDelimiter != listInfo.OrderedDelimiter ||
317|                currentParent.BulletType != listInfo.BulletType)
318|            {
319|                state.Close(currentParent);
320|                currentParent = null;
321|            }
322|        }
323|
324|        if (currentParent is null)
325|        {
326|            var newList = new ListBlock(this)
327|            {
328|                Column = initColumn,
329|                Span = new SourceSpan(sourcePosition, sourceEndPosition),
330|                IsOrdered = isOrdered,
331|                BulletType = listInfo.BulletType,
332|                OrderedDelimiter = listInfo.OrderedDelimiter,
333|                DefaultOrderedStart = listInfo.DefaultOrderedStart,
334|                OrderedStart = listInfo.OrderedStart,
335|            };
336|
337|            if (state.TrackTrivia)
338|            {
339|                newList.LinesBefore = state.TakeLinesBefore();
340|            }
341|
342|            state.NewBlocks.Push(newList);
343|        }
344|        return BlockState.Continue;
345|    }
346|
347|    /// <summary>
348|    /// Performs the close operation.
349|    /// </summary>
350|    public override bool Close(BlockProcessor processor, Block blockToClose)
351|    {
352|        if (processor.TrackTrivia)
353|        {
354|            return true;
355|        }
356|
357|        // Process only if we have blank lines
358|        if (blockToClose is ListBlock listBlock && listBlock.CountAllBlankLines > 0)
359|        {
360|            if (listBlock.Parent is ListItemBlock parentListItemBlock &&
361|                listBlock.LastChild is ListItemBlock lastListItem &&
362|                lastListItem.LastChild is BlankLineBlock)
363|            {
364|                // Inform the outer list that we have a blank line
365|                var parentList = (ListBlock)parentListItemBlock.Parent!;
366|
367|                parentList.CountAllBlankLines++;
368|                parentListItemBlock.Add(new BlankLineBlock());
369|            }
370|
371|            for (int listIndex = listBlock.Count - 1; listIndex >= 0; listIndex--)
372|            {
373|                var listItem = (ListItemBlock)listBlock[listIndex];
374|
375|                for (int i = listItem.Count - 1; i >= 0; i--)
376|                {
377|                    if (listItem[i] is BlankLineBlock)
378|                    {
379|                        if (i == listItem.Count - 1 ? listIndex < listBlock.Count - 1 : i > 0)
380|                        {
381|                            listBlock.IsLoose = true;
382|                        }
383|
384|                        listItem.RemoveAt(i);
385|
386|                        //If we have removed all blank lines, we can exit
387|                        listBlock.CountAllBlankLines--;
388|                        if (listBlock.CountAllBlankLines == 0)
389|                        {
390|                            goto done;
391|                        }
392|                    }
393|                }
394|            }
395|        }
396|
397|        done:
398|        return true;
399|    }
