9|/// <summary>
10|/// The default parser for parsing numbered list item (e.g: 1) or 1.)
11|/// </summary>
12|/// <seealso cref="OrderedListItemParser" />
13|public class NumberedListItemParser : OrderedListItemParser
14|{
15|    /// <summary>
16|    /// Initializes a new instance of the <see cref="NumberedListItemParser"/> class.
17|    /// </summary>
18|    public NumberedListItemParser()
19|    {
20|        OpeningCharacters = new char[10];
21|        for (int i = 0; i < 10; i++)
22|        {
23|            OpeningCharacters[i] = (char) ('0' + i);
24|        }
25|    }
26|
27|    /// <summary>
28|    /// Attempts to parse.
29|    /// </summary>
30|    public override bool TryParse(BlockProcessor state, char pendingBulletType, out ListInfo result)
31|    {
32|        result = new ListInfo();
33|        var c = state.CurrentChar;
34|        var sourcePosition = state.Start;
35|
36|        int countDigit = 0;
37|        int startChar = -1;
38|        int endChar = 0;
39|        while (c.IsDigit())
40|        {
41|            endChar = state.Start;
42|            // Trim left 0
43|            if (startChar < 0 && c != '0')
44|            {
45|                startChar = endChar;
46|            }
47|            c = state.NextChar();
48|            countDigit++;
49|        }
50|        var sourceBullet = new StringSlice(state.Line.Text, sourcePosition, state.Start - 1);
51|        if (startChar < 0)
52|        {
53|            startChar = endChar;
54|        }
55|
56|        // Note that ordered list start numbers must be nine digits or less:
57|        if (countDigit > 9 || !TryParseDelimiter(state, out char orderedDelimiter))
58|        {
59|            return false;
60|        }
61|
62|        if (startChar == endChar)
63|        {
64|            // Common case: a single digit character
65|            result.OrderedStart = CharHelper.SmallNumberToString(state.Line.Text[startChar] - '0');
66|        }
67|        else
68|        {
69|            result.OrderedStart = state.Line.Text.Substring(startChar, endChar - startChar + 1);
70|        }
71|
72|        result.OrderedDelimiter = orderedDelimiter;
73|        result.BulletType = '1';
74|        result.DefaultOrderedStart = "1";
75|        result.SourceBullet = sourceBullet;
76|        return true;
77|    }
