5|using Markdig.Helpers;
6|using Markdig.Syntax;
7|
8|using static Markdig.Syntax.CodeBlock;
9|
10|namespace Markdig.Parsers;
11|
12|/// <summary>
13|/// Block parser for an indented <see cref="CodeBlock"/>.
14|/// </summary>
15|/// <seealso cref="BlockParser" />
16|public class IndentedCodeBlockParser : BlockParser
17|{
18|    /// <summary>
19|    /// Determines whether interrupt.
20|    /// </summary>
21|    public override bool CanInterrupt(BlockProcessor processor, Block block)
22|    {
23|        return !block.IsParagraphBlock;
24|    }
25|
26|    /// <summary>
27|    /// Attempts to open a block at the current parser position.
28|    /// </summary>
29|    public override BlockState TryOpen(BlockProcessor processor)
30|    {
31|        var result = TryContinue(processor, null);
32|        if (result == BlockState.Continue)
33|        {
34|            // Save the column where we need to go back
35|            var column = processor.Column;
36|            var sourceStartPosition = processor.Start;
37|
38|            // Unwind all indents all spaces before in order to calculate correct span
39|            processor.UnwindAllIndents();
40|
41|            var codeBlock = new CodeBlock(this)
42|            {
43|                Column = processor.Column,
44|                Span = new SourceSpan(processor.Start, processor.Line.End),
45|            };
46|
47|            if (processor.TrackTrivia)
48|            {
49|                codeBlock.LinesBefore = processor.TakeLinesBefore();
50|                codeBlock.NewLine = processor.Line.NewLine;
51|            }
52|
53|            var codeBlockLine = new CodeBlockLine
54|            {
55|                TriviaBefore = processor.UseTrivia(sourceStartPosition - 1)
56|            };
57|            codeBlock.CodeBlockLines.Add(codeBlockLine);
58|            processor.NewBlocks.Push(codeBlock);
59|
60|            // Go back to the correct column
61|            processor.GoToColumn(column);
62|        }
63|        return result;
64|    }
65|
66|    /// <summary>
67|    /// Attempts to continue parsing the specified block.
68|    /// </summary>
69|    public override BlockState TryContinue(BlockProcessor processor, Block? block)
70|    {
71|        if (!processor.IsCodeIndent || processor.IsBlankLine)
72|        {
73|            if (block is null || !processor.IsBlankLine)
74|            {
75|                if (block != null)
76|                {
77|                    var codeBlock = (CodeBlock)block;
78|                    // add trailing blank lines to blank lines stack of processor
79|                    for (int i = codeBlock.Lines.Count - 1; i >= 0; i--)
80|                    {
81|                        var line = codeBlock.Lines.Lines[i];
82|                        if (line.Slice.IsEmpty)
83|                        {
84|                            codeBlock.Lines.RemoveAt(i);
85|
86|                            if (processor.TrackTrivia)
87|                            {
88|                                processor.LinesBefore ??= new List<StringSlice>();
89|                                processor.LinesBefore.Add(line.Slice);
90|                            }
91|                        }
92|                        else
93|                        {
94|                            break;
95|                        }
96|                    }
97|                }
98|                return BlockState.None;
99|            }
100|        }
101|
102|        // If we don't have a blank line, we reset to the indent
103|        if (processor.Indent > 4)
104|        {
105|            processor.GoToCodeIndent();
106|        }
107|        if (block != null)
108|        {
109|            block.UpdateSpanEnd(processor.Line.End);
110|
111|            // lines
112|            var cb = (CodeBlock)block;
113|            var codeBlockLine = new CodeBlockLine();
114|
115|            cb.CodeBlockLines.Add(codeBlockLine);
116|
117|            if (processor.TrackTrivia)
118|            {
119|                codeBlockLine.TriviaBefore = processor.UseTrivia(processor.Start - 1);
120|                cb.NewLine = processor.Line.NewLine; // ensure block newline is last newline
121|            }
122|        }
123|
124|        return BlockState.Continue;
125|    }
126|
127|    /// <summary>
128|    /// Performs the close operation.
129|    /// </summary>
130|    public override bool Close(BlockProcessor processor, Block block)
131|    {
132|        var codeBlock = (CodeBlock)block;
133|        if (codeBlock is null)
134|        {
135|            return true;
136|        }
137|
138|        // Remove any trailing blankline
139|        for (int i = codeBlock.Lines.Count - 1; i >= 0; i--)
140|        {
141|            var line = codeBlock.Lines.Lines[i];
142|            if (line.Slice.IsEmpty)
143|            {
144|                codeBlock.Lines.RemoveAt(i);
145|
146|                // if there are newlines after an indented codeblock, we must transform them
147|                // into empty lines after the block. as whitespace is stripped from the Line
148|                // we get that back from the beforeWhitespace on the CodeBlockLine.
149|                if (processor.TrackTrivia)
150|                {
151|                    var quoteLine = codeBlock.CodeBlockLines[i];
152|                    var emptyLine = new StringSlice(line.Slice.Text, quoteLine.TriviaBefore.Start, line.Slice.End, line.NewLine);
153|                    block.LinesAfter ??= new List<StringSlice>();
154|                    block.LinesAfter.Add(emptyLine);
155|                }
156|            }
157|            else
158|            {
159|                break;
160|            }
161|        }
162|        return true;
163|    }
