5|using Markdig.Helpers;
6|using Markdig.Syntax;
7|
8|namespace Markdig.Parsers;
9|
10|/// <summary>
11|/// Block parser for a <see cref="ParagraphBlock"/>.
12|/// </summary>
13|/// <seealso cref="BlockParser" />
14|public class ParagraphBlockParser : BlockParser
15|{
16|    /// <summary>
17|    /// Gets or sets the parse setex headings.
18|    /// </summary>
19|    public bool ParseSetexHeadings { get; set; } = true;
20|
21|    /// <summary>
22|    /// Attempts to open a block at the current parser position.
23|    /// </summary>
24|    public override BlockState TryOpen(BlockProcessor processor)
25|    {
26|        if (processor.IsBlankLine)
27|        {
28|            return BlockState.None;
29|        }
30|
31|        // We continue trying to match by default
32|        var paragraph = new ParagraphBlock(this)
33|        {
34|            Column = processor.Column,
35|            Span = new SourceSpan(processor.Line.Start, processor.Line.End),
36|        };
37|
38|        if (processor.TrackTrivia)
39|        {
40|            paragraph.LinesBefore = processor.TakeLinesBefore();
41|            paragraph.NewLine = processor.Line.NewLine;
42|        }
43|
44|        processor.NewBlocks.Push(paragraph);
45|        return BlockState.Continue;
46|    }
47|
48|    /// <summary>
49|    /// Attempts to continue parsing the specified block.
50|    /// </summary>
51|    public override BlockState TryContinue(BlockProcessor processor, Block block)
52|    {
53|        if (processor.IsBlankLine)
54|        {
55|            return BlockState.BreakDiscard;
56|        }
57|
58|        if (!processor.IsCodeIndent && ParseSetexHeadings)
59|        {
60|            return TryParseSetexHeading(processor, block);
61|        }
62|        block.NewLine = processor.Line.NewLine;
63|        block.UpdateSpanEnd(processor.Line.End);
64|        return BlockState.Continue;
65|    }
66|
67|    /// <summary>
68|    /// Performs the close operation.
69|    /// </summary>
70|    public override bool Close(BlockProcessor processor, Block block)
71|    {
72|        if (block is ParagraphBlock paragraph)
73|        {
74|            ref var lines = ref paragraph.Lines;
75|
76|            if (processor.TrackTrivia)
77|            {
78|                TryMatchLinkReferenceDefinitionTrivia(ref lines, processor, paragraph);
79|            }
80|            else
81|            {
82|                TryMatchLinkReferenceDefinition(ref lines, processor);
83|            }
84|
85|            int lineCount = lines.Count;
86|
87|            // If Paragraph is empty, we can discard it
88|            if (lineCount == 0)
89|            {
90|                return false;
91|            }
92|
93|            if (!processor.TrackTrivia)
94|            {
95|                for (int i = 0; i < lineCount; i++)
96|                {
97|                    lines.Lines[i].Slice.TrimStart();
98|                }
99|                lines.Lines[lineCount - 1].Slice.TrimEnd();
100|            }
101|        }
102|
103|        return true;
104|    }
105|
106|    private BlockState TryParseSetexHeading(BlockProcessor state, Block block)
107|    {
108|        var line = state.Line;
109|        var sourcePosition = line.Start;
110|        int count = 0;
111|        char headingChar = GetHeadingChar(ref line, ref count);
112|
113|        if (headingChar != 0)
114|        {
115|            var paragraph = (ParagraphBlock)block;
116|
117|            bool foundLrd;
118|            if (state.TrackTrivia)
119|            {
120|                foundLrd = TryMatchLinkReferenceDefinitionTrivia(ref paragraph.Lines, state, paragraph);
121|            }
122|            else
123|            {
124|                foundLrd = TryMatchLinkReferenceDefinition(ref paragraph.Lines, state);
125|            }
126|
127|            // If we matched a LinkReferenceDefinition before matching the heading, and the remaining
128|            // lines are empty, we can early exit and remove the paragraph
129|            var parent = block.Parent;
130|            bool isSetTextHeading = !state.IsLazy || paragraph.Column == state.Column || !(parent is QuoteBlock || parent is ListItemBlock);
131|            if (!(foundLrd && paragraph.Lines.Count == 0) && isSetTextHeading)
132|            {
133|                // We discard the paragraph that will be transformed to a heading
134|                state.Discard(paragraph);
135|
136|                while (state.CurrentChar == headingChar)
137|                {
138|                    state.NextChar();
139|                }
140|
141|                int level = headingChar == '=' ? 1 : 2;
142|
143|                var heading = new HeadingBlock(this)
144|                {
145|                    Column = paragraph.Column,
146|                    Span = new SourceSpan(paragraph.Span.Start, line.End),
147|                    Level = level,
148|                    Lines = paragraph.Lines,
149|                    IsSetext = true,
150|                    HeaderCharCount = count,
151|                };
152|
153|                if (state.TrackTrivia)
154|                {
155|                    heading.LinesBefore = paragraph.LinesBefore;
156|                    heading.TriviaBefore = state.UseTrivia(sourcePosition - 1); // remove dashes
157|                    heading.TriviaAfter = new StringSlice(state.Line.Text, state.Start, line.End);
158|                    heading.NewLine = state.Line.NewLine;
159|                    heading.SetextNewline = paragraph.NewLine;
160|                }
161|                else
162|                {
163|                    heading.Lines.Trim();
164|                }
165|
166|                // Remove the paragraph as a pending block
167|                state.NewBlocks.Push(heading);
168|
169|                return BlockState.BreakDiscard;
170|            }
171|        }
172|
173|        block.UpdateSpanEnd(state.Line.End);
174|
175|        return BlockState.Continue;
176|    }
177|
178|    private static char GetHeadingChar(ref StringSlice line, ref int count)
179|    {
180|        char headingChar = line.CurrentChar;
181|
182|        if (headingChar == '=' || headingChar == '-')
183|        {
184|            count = line.CountAndSkipChar(headingChar);
185|
186|            while (line.CurrentChar.IsSpaceOrTab())
187|            {
188|                line.NextChar();
189|            }
190|
191|            if (line.IsEmpty)
192|            {
193|                return headingChar;
194|            }
195|        }
196|
197|        return (char)0;
198|    }
199|
200|    private static bool TryMatchLinkReferenceDefinition(ref StringLineGroup lines, BlockProcessor state)
201|    {
202|        bool atLeastOneFound = false;
203|
204|        while (true)
205|        {
206|            // If we have found a LinkReferenceDefinition, we can discard the previous paragraph
207|            var iterator = lines.ToCharIterator();
208|            if (LinkReferenceDefinition.TryParse(ref iterator, out LinkReferenceDefinition? linkReferenceDefinition))
209|            {
210|                state.Document.SetLinkReferenceDefinition(linkReferenceDefinition.Label!, linkReferenceDefinition, true);
211|                atLeastOneFound = true;
212|
213|                // Correct the locations of each field
214|                linkReferenceDefinition.Line = lines.Lines[0].Line;
215|
216|                linkReferenceDefinition.Span = lines.ConvertToAbsoluteSpan(linkReferenceDefinition.Span);
217|                linkReferenceDefinition.LabelSpan = lines.ConvertToAbsoluteSpan(linkReferenceDefinition.LabelSpan);
218|                linkReferenceDefinition.UrlSpan = lines.ConvertToAbsoluteSpan(linkReferenceDefinition.UrlSpan);
219|                linkReferenceDefinition.TitleSpan = lines.ConvertToAbsoluteSpan(linkReferenceDefinition.TitleSpan);
220|                lines = iterator.Remaining();
221|            }
222|            else
223|            {
224|                break;
225|            }
226|        }
227|
228|        return atLeastOneFound;
229|    }
230|
231|    private static bool TryMatchLinkReferenceDefinitionTrivia(ref StringLineGroup lines, BlockProcessor state, ParagraphBlock paragraph)
232|    {
233|        bool atLeastOneFound = false;
234|
235|        while (true)
236|        {
237|            // If we have found a LinkReferenceDefinition, we can discard the previous paragraph
238|            var iterator = lines.ToCharIterator();
239|            if (LinkReferenceDefinition.TryParseTrivia(
240|                ref iterator,
241|                out LinkReferenceDefinition? lrd,
242|                out SourceSpan triviaBeforeLabel,
243|                out SourceSpan labelWithTrivia,
244|                out SourceSpan triviaBeforeUrl,
245|                out SourceSpan unescapedUrl,
246|                out SourceSpan triviaBeforeTitle,
247|                out SourceSpan unescapedTitle,
248|                out SourceSpan triviaAfterTitle))
249|            {
250|                state.Document.SetLinkReferenceDefinition(lrd.Label!, lrd, false);
251|                lrd.Parent = null; // remove LRDG parent from lrd
252|                atLeastOneFound = true;
253|
254|                // Correct the locations of each field
255|                lrd.Line = lines.Lines[0].Line;
256|                var text = lines.Lines[0].Slice.Text;
257|
258|                triviaBeforeLabel = lines.ConvertToAbsoluteSpan(triviaBeforeLabel);
259|                labelWithTrivia = lines.ConvertToAbsoluteSpan(labelWithTrivia);
260|                triviaBeforeUrl = lines.ConvertToAbsoluteSpan(triviaBeforeUrl);
261|                unescapedUrl = lines.ConvertToAbsoluteSpan(unescapedUrl);
262|                triviaBeforeTitle = lines.ConvertToAbsoluteSpan(triviaBeforeTitle);
263|                unescapedTitle = lines.ConvertToAbsoluteSpan(unescapedTitle);
264|                triviaAfterTitle = lines.ConvertToAbsoluteSpan(triviaAfterTitle);
265|                lrd.Span = lines.ConvertToAbsoluteSpan(lrd.Span);
266|                lrd.TriviaBefore = new StringSlice(text, triviaBeforeLabel.Start, triviaBeforeLabel.End);
267|                lrd.LabelSpan = lines.ConvertToAbsoluteSpan(lrd.LabelSpan);
268|                lrd.LabelWithTrivia = new StringSlice(text, labelWithTrivia.Start, labelWithTrivia.End);
269|                lrd.TriviaBeforeUrl = new StringSlice(text, triviaBeforeUrl.Start, triviaBeforeUrl.End);
