5|using Markdig.Syntax;
6|using Markdig.Syntax.Inlines;
7|
8|namespace Markdig.Renderers.Roundtrip;
9|
10|/// <summary>
11|/// A Roundtrip renderer for a <see cref="QuoteBlock"/>.
12|/// </summary>
13|public class QuoteBlockRenderer : RoundtripObjectRenderer<QuoteBlock>
14|{
15|    /// <summary>
16|    /// Writes the object to the specified renderer.
17|    /// </summary>
18|    protected override void Write(RoundtripRenderer renderer, QuoteBlock quoteBlock)
19|    {
20|        renderer.RenderLinesBefore(quoteBlock);
21|        renderer.Write(quoteBlock.TriviaBefore);
22|
23|        var indents = new string[quoteBlock.QuoteLines.Count];
24|        for (int i = 0; i < quoteBlock.QuoteLines.Count; i++)
25|        {
26|            var quoteLine = quoteBlock.QuoteLines[i];
27|            var wsb = quoteLine.TriviaBefore.ToString();
28|            var quoteChar = quoteLine.QuoteChar ? ">" : "";
29|            var spaceAfterQuoteChar = quoteLine.HasSpaceAfterQuoteChar ? " " : "";
30|            var wsa = quoteLine.TriviaAfter.ToString();
31|            indents[i] = (wsb + quoteChar + spaceAfterQuoteChar + wsa);
32|        }
33|        bool noChildren = false;
34|        if (quoteBlock.Count == 0)
35|        {
36|            noChildren = true;
37|            // since this QuoteBlock instance has no children, indents will not be rendered. We
38|            // work around this by adding empty LineBreakInlines to a ParagraphBlock.
39|            // Wanted: a more elegant/better solution (although this is not *that* bad).
40|            foreach (var quoteLine in quoteBlock.QuoteLines)
41|            {
42|                var emptyLeafBlock = new ParagraphBlock
43|                {
44|                    NewLine = quoteLine.NewLine
45|                };
46|                var newLine = new LineBreakInline
47|                {
48|                    NewLine = quoteLine.NewLine
49|                };
50|                var container = new ContainerInline();
51|                container.AppendChild(newLine);
52|                emptyLeafBlock.Inline = container;
53|                quoteBlock.Add(emptyLeafBlock);
54|            }
55|        }
56|
57|        renderer.PushIndent(indents);
58|        renderer.WriteChildren(quoteBlock);
59|        renderer.PopIndent();
60|
61|        if (!noChildren)
62|        {
63|            renderer.RenderLinesAfter(quoteBlock);
64|        }
65|    }
66|}

