12|/// <summary>
13|/// Markdown renderer honoring trivia for a  <see cref="MarkdownDocument"/> object.
14|/// </summary>
15|/// Ensure to call the <see cref="MarkdownExtensions.EnableTrackTrivia"/> extension method when
16|/// parsing markdown to have trivia available for rendering.
17|public class RoundtripRenderer : TextRendererBase<RoundtripRenderer>
18|{
19|    /// <summary>
20|    /// Initializes a new instance of the <see cref="RoundtripRenderer"/> class.
21|    /// </summary>
22|    /// <param name="writer">The writer.</param>
23|    public RoundtripRenderer(TextWriter writer) : base(writer)
24|    {
25|        // Default block renderers
26|        ObjectRenderers.Add(new CodeBlockRenderer());
27|        ObjectRenderers.Add(new ListRenderer());
28|        ObjectRenderers.Add(new HeadingRenderer());
29|        ObjectRenderers.Add(new HtmlBlockRenderer());
30|        ObjectRenderers.Add(new ParagraphRenderer());
31|        ObjectRenderers.Add(new QuoteBlockRenderer());
32|        ObjectRenderers.Add(new ThematicBreakRenderer());
33|        ObjectRenderers.Add(new LinkReferenceDefinitionGroupRenderer());
34|        ObjectRenderers.Add(new LinkReferenceDefinitionRenderer());
35|        ObjectRenderers.Add(new EmptyBlockRenderer());
36|
37|        // Default inline renderers
38|        ObjectRenderers.Add(new AutolinkInlineRenderer());
39|        ObjectRenderers.Add(new CodeInlineRenderer());
40|        ObjectRenderers.Add(new DelimiterInlineRenderer());
41|        ObjectRenderers.Add(new EmphasisInlineRenderer());
42|        ObjectRenderers.Add(new LineBreakInlineRenderer());
43|        ObjectRenderers.Add(new RoundtripHtmlInlineRenderer());
44|        ObjectRenderers.Add(new RoundtripHtmlEntityInlineRenderer());            
45|        ObjectRenderers.Add(new LinkInlineRenderer());
46|        ObjectRenderers.Add(new LiteralInlineRenderer());
47|    }
48|
49|    /// <summary>
50|    /// Writes the lines of a <see cref="LeafBlock"/>
51|    /// </summary>
52|    /// <param name="leafBlock">The leaf block.</param>
53|    /// <returns>This instance</returns>
54|    public void WriteLeafRawLines(LeafBlock leafBlock)
55|    {
56|        if (leafBlock is null) ThrowHelper.ArgumentNullException_leafBlock();
57|        if (leafBlock.Lines.Lines != null)
58|        {
59|            var lines = leafBlock.Lines;
60|            var slices = lines.Lines;
61|            for (int i = 0; i < lines.Count; i++)
62|            {
63|                var slice = slices[i].Slice;
64|                Write(ref slice);
65|                WriteLine(slice.NewLine);
66|            }
67|        }
68|    }
69|
70|    /// <summary>
71|    /// Performs the render lines before operation.
72|    /// </summary>
73|    public void RenderLinesBefore(Block block)
74|    {
75|        if (block.LinesBefore is null)
76|        {
77|            return;
78|        }
79|        foreach (var line in block.LinesBefore)
80|        {
81|            Write(line);
82|            WriteLine(line.NewLine);
83|        }
84|    }
85|
86|    /// <summary>
87|    /// Performs the render lines after operation.
88|    /// </summary>
89|    public void RenderLinesAfter(Block block)
90|    {
91|        previousWasLine = true;
92|        if (block.LinesAfter is null)
93|        {
94|            return;
95|        }
96|        foreach (var line in block.LinesAfter)
97|        {
98|            Write(line);
99|            WriteLine(line.NewLine);
100|        }
101|    }
