15|/// <summary>
16|/// A text based <see cref="IMarkdownRenderer"/>.
17|/// </summary>
18|/// <seealso cref="RendererBase" />
19|public abstract class TextRendererBase : RendererBase
20|{
21|    private TextWriter _writer;
22|
23|    /// <summary>
24|    /// Initializes a new instance of the <see cref="TextRendererBase"/> class.
25|    /// </summary>
26|    /// <param name="writer">The writer.</param>
27|    /// <exception cref="ArgumentNullException"></exception>
28|    protected TextRendererBase(TextWriter writer)
29|    {
30|        Writer = writer;
31|    }
32|
33|    /// <summary>
34|    /// Gets or sets the writer.
35|    /// </summary>
36|    /// <exception cref="ArgumentNullException">if the value is null</exception>
37|    public TextWriter Writer
38|    {
39|        get => _writer;
40|        [MemberNotNull(nameof(_writer))]
41|        set
42|        {
43|            if (value is null)
44|            {
45|                ThrowHelper.ArgumentNullException(nameof(value));
46|            }
47|
