29|                    renderer.WriteRaw(listBlock.BulletType);
30|                    renderer.WriteRaw('"');
31|                }
32|
33|                if (listBlock.OrderedStart is not null && listBlock.OrderedStart != "1")
34|                {
35|                    renderer.Write(" start=\"");
36|                    renderer.WriteRaw(listBlock.OrderedStart);
37|                    renderer.WriteRaw('"');
38|                }
