40|                renderer.WriteLine('>');
41|            }
42|            else
43|            {
44|                renderer.Write("<ul");
45|                renderer.WriteAttributes(listBlock);
46|                renderer.WriteLine('>');
47|            }
48|        }
49|
50|        foreach (var item in listBlock)
51|        {
52|            var listItem = (ListItemBlock)item;
53|            var previousImplicit = renderer.ImplicitParagraph;
54|            renderer.ImplicitParagraph = !listBlock.IsLoose;
55|
